"""The two deliberately authored, visual-first films. This is not an LLM fallback."""
from pathlib import Path
import json
from stickfilm.schema import Plan


def k(at,x=800,y=765,pose='rest',emotion='neutral',scale=1.4,facing=1,angle=0,alpha=1,mark=0):
 return dict(at=at,x=x,y=y,pose=pose,emotion=emotion,scale=scale,facing=facing,angle=angle,alpha=alpha,mark=mark)
def actor(name,look,x=800,pose='rest',end='rest',emotion='neutral',feeling=None,to=None,y=765,scale=1.4,facing=1,carry='none',mark=0,endmark=None,keys=None):
 start=k(0,x,y,pose,emotion,scale,facing,mark=mark)
 stop=k(1,x if to is None else to,y,end,feeling or emotion,scale,facing,mark=mark if endmark is None else endmark)
 if keys is None:
  if to is None:
   keys=[start,dict(start,at=.12),dict(stop,at=.62),stop]
  else:keys=[start,stop]
 return dict(name=name,look=look,carry=carry,keys=keys)
def obj(kind,x,y=700,to=None,ty=None,scale=1,end_scale=None,angle=0,turn=None,alpha=1,end_alpha=1,label='',color='#efc377',keys=None):
 return dict(kind=kind,label=label,color=color,keys=keys or [dict(at=0,x=x,y=y,scale=scale,angle=angle,alpha=alpha),dict(at=1,x=x if to is None else to,y=y if ty is None else ty,scale=scale if end_scale is None else end_scale,angle=angle if turn is None else turn,alpha=end_alpha)])
def lens(x=800,y=450,z=1,to=None,ty=None,end=None):return [dict(at=0,x=x,y=y,zoom=z),dict(at=1,x=x if to is None else to,y=y if ty is None else ty,zoom=z if end is None else end)]
F=lambda **kw:actor('Eli','father',**kw)
D=lambda **kw:actor('June','daughter',scale=.95,**kw)
B=lambda **kw:actor('Voss','boss',**kw)
C=lambda **kw:actor('Alex','colleague',**kw)
P=lambda **kw:actor('Mara','partner',**kw)
W=lambda **kw:actor('Noah','witness',**kw)
M=lambda **kw:actor('Rosa','mother',**kw)
R=lambda **kw:actor('Lena','friend',**kw)
U=lambda **kw:actor('Dane','bully',**kw)
films={}

def build(key,title,brief,niche,palette):
 shots=[]
 def add(world,actors,note,*,voice='',say='',items=None,cam=None,time='day',seconds=6,music='curious',cue='whoosh'):
  i=len(shots);beat='hook' if i<2 else 'setup' if i<10 else 'payoff' if i>=43 else 'conflict' if 24<=i<=35 else 'progression'
  if i==49:beat='closing'
  shots.append(dict(id=f'{key}-v2-{i+1:02}',beat=beat,narration=voice or say,label='',environment='abstract',actors=[dict(character='hero',action='idle')],camera='wide',music=music,pause=.3,directed_seconds=seconds,duration=seconds,cinema=dict(world=world,palette=palette,time=time,performers=actors,items=items or [],lens=cam or lens(),caption=say,voice=actors[0]['look'] if say else 'narrator',note=note),cues=[dict(at=.45,kind=cue,gain=.22)] if cue else []))
 def finish():
  assert len(shots)==50,len(shots)
  overrides={'psychology':{3:'daughter',14:'daughter',44:'colleague'},'what-if':{3:'bully',16:'friend',25:'friend',42:'witness',44:'bully'}}
  for shot in shots:
   number=int(shot['id'].split('-')[-1])
   if number in overrides[key]:shot['cinema']['voice']=overrides[key][number]
   if key=='psychology' and shot['id'].endswith('-46'):
    for item in shot['cinema']['items']:
     if item['kind']=='box':item['kind']='platform';item['keys'][0]['scale']=item['keys'][1]['scale']=1
     if item['kind']=='chair':item['keys'][0]['scale']=item['keys'][1]['scale']=1.4
   for performer in shot['cinema']['performers']:
    if performer['keys'][-1]['x']<performer['keys'][0]['x']-50:
     for keyframe in performer['keys']:keyframe['facing']=-1
    if performer['look']=='mother' and shot['cinema']['world']=='hospital':
     for keyframe in performer['keys']:
      if keyframe['pose'] in ('offer','cover','hold'):keyframe['pose']='sit_'+keyframe['pose']
    if performer['look']=='father' and shot['cinema']['world']=='home' and any(p['look']=='daughter' for p in shot['cinema']['performers']):
     # Preserve adult eye level for the child's physical embrace and shared work.
     if any(kf['pose']=='kneel' for kf in performer['keys']) or len(shots)>45:
      for keyframe in performer['keys']:
       if keyframe['pose'] in ('hug','write','reach') and shot['id'].split('-')[-1] in ('42','48','49','50'):keyframe['pose']='kneel_'+keyframe['pose']
  plan=Plan(title=title,brief=brief,niche=niche,requested_minutes=5,seed=712 if key=='psychology' else 911,provenance='reviewed-plan',factual_status='fiction',scenes=shots)
  Path(f'episodes/{key}.json').write_text(plan.model_dump_json(indent=2)+'\n');films[key]=plan
  print(key,'shots',len(shots),'directed_seconds',sum(s.directed_seconds for s in plan.scenes),'spoken_words',sum(len(s.narration.split()) for s in plan.scenes))
 return add,finish

