for key,p in films.items():
 out=Path('docs/episodes');out.mkdir(exist_ok=True)
 lines=['# '+p.title,'','An original fictional short. Sparse speech; the action column is the actual story.','', '| Shot | Seconds | Visible action and emotional turn | Spoken words |','|---|---:|---|---|']
 for i,s in enumerate(p.scenes):lines.append(f'| {i+1:02} | {s.directed_seconds:g} | {s.cinema.note} | {s.narration or "—"} |')
 (out/f'{key}-v2-screenplay.md').write_text('\n'.join(lines)+'\n')
